[
  {
    "level": "Intermediate",
    "module_name": "Present Continuous",
    "sub_topic_title": "Form and Usage of Present Continuous",
    "objective": "Understand how to form the present continuous tense and when to use it for actions happening at the moment of speaking.",
    "vocabulary": [
      {
        "term": "Currently",
        "meaning": "Saat ini"
      },
      {
        "term": "Nowadays",
        "meaning": "Zaman sekarang / Saat ini"
      },
      {
        "term": "Temporary",
        "meaning": "Sementara"
      },
      {
        "term": "Annoying habits",
        "meaning": "Kebiasaan yang mengganggu (menggunakan 'always')"
      },
      {
        "term": "In progress",
        "meaning": "Sedang berlangsung"
      }
    ],
    "concept": "The present continuous is formed with 'to be' (am/is/are) + Verb-ing. Use it for actions happening right now (e.g., 'I am reading'), temporary situations (e.g., 'She is staying with her friend this week'), and trends (e.g., 'Prices are rising'). We can also use it with 'always' to express annoyance (e.g., 'He is always complaining').",
    "example_dialogue": "A: Are you working on the new project right now?\nB: Yes, I am currently writing the report. It is taking longer than expected.\nA: I know. The requirements are changing constantly.\nB: Exactly! And the client is always asking for new features."
  },
  {
    "level": "Intermediate",
    "module_name": "Present Continuous",
    "sub_topic_title": "State Verbs vs Action Verbs",
    "objective": "Learn to distinguish between action verbs (which can be used in continuous form) and state verbs (which generally cannot).",
    "vocabulary": [
      {
        "term": "Action verb",
        "meaning": "Kata kerja aksi (contoh: run, eat, play)"
      },
      {
        "term": "State verb",
        "meaning": "Kata kerja keadaan (contoh: know, like, belong)"
      },
      {
        "term": "Understand",
        "meaning": "Memahami"
      },
      {
        "term": "Believe",
        "meaning": "Percaya"
      },
      {
        "term": "Realize",
        "meaning": "Menyadari"
      }
    ],
    "concept": "Action verbs describe physical actions and can take the continuous form. State verbs describe emotions, possession, senses, or thoughts, and are NOT used in the continuous form. (Correct: 'I know him'. Incorrect: 'I am knowing him'). Some verbs can be both, with different meanings. For example, 'I think it's a good idea' (opinion = state), but 'I am thinking about my holiday' (mental process = action).",
    "example_dialogue": "A: Do you understand the new instructions for the assignment?\nB: Yes, I do. But I am still figuring out the specific details.\nA: Good. I believe you can finish it by Friday. Does this laptop belong to you?\nB: No, I am just using it for today. It belongs to Sarah."
  },
  {
    "level": "Intermediate",
    "module_name": "Present Continuous",
    "sub_topic_title": "Present Continuous for Future Arrangements",
    "objective": "Learn how to use the present continuous tense to talk about planned future events.",
    "vocabulary": [
      {
        "term": "Arrangement",
        "meaning": "Rencana / Susunan acara yang sudah pasti"
      },
      {
        "term": "Schedule",
        "meaning": "Jadwal"
      },
      {
        "term": "Appointment",
        "meaning": "Janji temu"
      },
      {
        "term": "Fixed",
        "meaning": "Tetap / Sudah dipastikan"
      }
    ],
    "concept": "The present continuous can be used to talk about future plans that have already been confirmed or arranged. Time words like 'tomorrow', 'next week', or 'on Monday' are usually added. Example: 'I am meeting the doctor tomorrow at 3 PM' (The appointment is booked).",
    "example_dialogue": "A: What are you doing this weekend?\nB: I am flying to London on Saturday morning. I already bought the tickets.\nA: That's exciting! Are you staying there for a long time?\nB: No, I am returning on Tuesday. I am having a business meeting on Monday."
  }
]

[
  {
    "level": "Intermediate",
    "module_name": "Past Simple",
    "sub_topic_title": "Regular and Irregular Verbs in Past Simple",
    "objective": "Master the formation of past simple tense using both regular (-ed) and irregular verbs to talk about completed actions.",
    "vocabulary": [
      {
        "term": "Yesterday",
        "meaning": "Kemarin"
      },
      {
        "term": "Last week / Last year",
        "meaning": "Minggu lalu / Tahun lalu"
      },
      {
        "term": "Ago",
        "meaning": "Yang lalu (contoh: 2 days ago)"
      },
      {
        "term": "Completed",
        "meaning": "Selesai / Lengkap"
      },
      {
        "term": "Occurred",
        "meaning": "Terjadi"
      }
    ],
    "concept": "Use the Past Simple for actions that started and finished at a specific time in the past. Regular verbs add '-ed' (work -> worked). Irregular verbs change form completely (go -> went, buy -> bought). In negative sentences and questions, use the auxiliary 'did' + base verb (e.g., 'Did you go?', 'I didn't see it').",
    "example_dialogue": "A: Where did you go last weekend?\nB: I went to the mountains with my family. We hiked for three hours on Saturday.\nA: That sounds amazing! Did you see any wildlife during the hike?\nB: Yes, we saw a deer and many beautiful birds. We didn't see any bears, thankfully!"
  },
  {
    "level": "Intermediate",
    "module_name": "Past Simple",
    "sub_topic_title": "Past Habits (Used to vs Past Simple)",
    "objective": "Understand how to express past habits and routines that are no longer true in the present.",
    "vocabulary": [
      {
        "term": "Used to",
        "meaning": "Dulu sering / Terbiasa di masa lalu"
      },
      {
        "term": "Habit",
        "meaning": "Kebiasaan"
      },
      {
        "term": "Routine",
        "meaning": "Rutinitas"
      },
      {
        "term": "No longer",
        "meaning": "Tidak lagi"
      }
    ],
    "concept": "'Used to' + base verb is used for habits, routines, or states that existed in the past but are not true now (e.g., 'I used to play tennis when I was young'). You can also use the Past Simple for this, but 'used to' emphasizes the contrast with the present. For negative sentences, use 'didn't use to' (e.g., 'She didn't use to like coffee').",
    "example_dialogue": "A: I didn't use to like vegetables when I was a kid.\nB: Really? I used to eat everything my mother cooked. Did you use to play any sports?\nA: Yes, I played soccer a lot. I used to be the captain of the school team.\nB: Wow! Do you still play?\nA: No, I stopped playing two years ago. I don't have the time anymore."
  }
]

[
  {
    "level": "Intermediate",
    "module_name": "Present Perfect",
    "sub_topic_title": "Life Experiences and Unspecified Time",
    "objective": "Learn to use the present perfect tense to describe life experiences without mentioning a specific time.",
    "vocabulary": [
      {
        "term": "Ever",
        "meaning": "Pernah (digunakan dalam pertanyaan)"
      },
      {
        "term": "Never",
        "meaning": "Tidak pernah"
      },
      {
        "term": "Before",
        "meaning": "Sebelumnya"
      },
      {
        "term": "Experience",
        "meaning": "Pengalaman"
      }
    ],
    "concept": "The present perfect is formed with 'have/has' + past participle (Verb 3). We use it to talk about experiences in our life up to now. The exact time is not important or not known. Words like 'ever' and 'never' are common. Example: 'I have visited Japan three times.'",
    "example_dialogue": "A: Have you ever eaten authentic Mexican food?\nB: Yes, I have. I tried it when I visited California. Have you?\nA: No, I have never tried it. I have always wanted to, though.\nB: We should go to the new Mexican restaurant downtown. I've heard it's fantastic."
  },
  {
    "level": "Intermediate",
    "module_name": "Present Perfect",
    "sub_topic_title": "Actions Continuing up to the Present (Since / For)",
    "objective": "Understand how to describe states or actions that started in the past and continue into the present.",
    "vocabulary": [
      {
        "term": "Since",
        "meaning": "Sejak (menunjukkan titik awal waktu)"
      },
      {
        "term": "For",
        "meaning": "Selama (menunjukkan durasi waktu)"
      },
      {
        "term": "Duration",
        "meaning": "Durasi"
      },
      {
        "term": "Recently",
        "meaning": "Baru-baru ini"
      }
    ],
    "concept": "We use the present perfect with 'for' and 'since' for situations that started in the past and are still true now. Use 'for' with a period of time (e.g., for ten years, for two months). Use 'since' with a specific point in time (e.g., since 2010, since last Monday).",
    "example_dialogue": "A: How long have you lived in this city?\nB: I have lived here for five years. What about you?\nA: I have been here since 2018. It's a great place to live.\nB: I agree. I have worked at my current company since I moved here, and I love it."
  },
  {
    "level": "Intermediate",
    "module_name": "Present Perfect",
    "sub_topic_title": "Present Perfect vs Past Simple",
    "objective": "Master the difference between finished past time (Past Simple) and unfinished time (Present Perfect).",
    "vocabulary": [
      {
        "term": "Finished time",
        "meaning": "Waktu yang sudah berakhir (misal: kemarin)"
      },
      {
        "term": "Unfinished time",
        "meaning": "Waktu yang masih berlanjut (misal: hari ini, minggu ini)"
      },
      {
        "term": "Just",
        "meaning": "Baru saja"
      },
      {
        "term": "Impact",
        "meaning": "Dampak / Pengaruh"
      }
    ],
    "concept": "Use Past Simple with finished time words (yesterday, last year, in 1999). Use Present Perfect with unfinished time words (today, this week, so far) or when a past action has a direct result in the present (e.g., 'I have lost my keys' -> I don't have them now).",
    "example_dialogue": "A: Did you see David yesterday?\nB: No, I didn't see him yesterday, but I have seen him this morning.\nA: Oh, good. Have you finished the financial report yet?\nB: Yes, I finished it last night. I have already sent it to the manager."
  }
]

[
  {
    "level": "Advanced",
    "module_name": "Advanced Grammar",
    "sub_topic_title": "Mixed Conditionals",
    "objective": "Master complex conditional structures to express hypothetical situations linking past conditions to present results.",
    "vocabulary": [
      {
        "term": "Hypothetical",
        "meaning": "Bersifat hipotesis / dugaan tak nyata"
      },
      {
        "term": "Condition / Result",
        "meaning": "Kondisi / Hasil"
      },
      {
        "term": "Contrary to fact",
        "meaning": "Bertentangan dengan fakta"
      },
      {
        "term": "Consequently",
        "meaning": "Akibatnya"
      }
    ],
    "concept": "Mixed conditionals blend elements of 2nd and 3rd conditionals. The most common form mixes a past condition (If + Past Perfect) with a present result (would + base verb). Example: 'If I had studied harder (past), I would have a better job now (present).'",
    "example_dialogue": "A: Did you accept that startup job offer in Berlin last year?\nB: No, I turned it down. If I had accepted it, I would be living in Germany right now.\nA: That's a huge life change. Do you regret it?\nB: Not really. If I weren't happy with my current career, I might have regretted it, but I love my current team."
  },
  {
    "level": "Advanced",
    "module_name": "Advanced Grammar",
    "sub_topic_title": "The Subjunctive Mood",
    "objective": "Understand the nuances of the subjunctive mood in formal English and academic writing.",
    "vocabulary": [
      {
        "term": "Subjunctive",
        "meaning": "Modus pengandaian/keharusan formal"
      },
      {
        "term": "Imperative",
        "meaning": "Sangat penting / Mengharuskan"
      },
      {
        "term": "Mandatory",
        "meaning": "Wajib"
      },
      {
        "term": "Crucial",
        "meaning": "Sangat krusial / penting"
      }
    ],
    "concept": "The subjunctive mood is used after verbs of urgency, recommendation, or demand (recommend, suggest, insist) and adjectives like 'essential' or 'crucial'. It requires the base form of the verb, ignoring subject-verb agreement rules. Example: 'It is essential that she arrive (not arrives) on time.'",
    "example_dialogue": "A: The board recommended that the CEO step down immediately.\nB: I agree. It is crucial that the company restructure its leadership before the next quarter.\nA: Exactly. The investors insist that a new strategy be implemented as soon as possible."
  },
  {
    "level": "Advanced",
    "module_name": "Advanced Grammar",
    "sub_topic_title": "Inversion for Emphasis",
    "objective": "Learn how to use subject-auxiliary inversion to add dramatic emphasis and formality to your writing.",
    "vocabulary": [
      {
        "term": "Inversion",
        "meaning": "Pembalikan struktur kalimat"
      },
      {
        "term": "Emphasis",
        "meaning": "Penekanan"
      },
      {
        "term": "Rarely / Seldom",
        "meaning": "Jarang"
      },
      {
        "term": "Under no circumstances",
        "meaning": "Dalam keadaan apapun tidak..."
      }
    ],
    "concept": "In formal or literary English, when a negative or restrictive adverb (like never, rarely, seldom, not only) is placed at the beginning of a sentence, the subject and the auxiliary verb are inverted. Example: 'Never have I seen such a brilliant performance.' (Instead of 'I have never seen...')",
    "example_dialogue": "A: The recent economic summit was unprecedented.\nB: Indeed. Rarely do we witness such unanimous agreement among global leaders.\nA: Not only did they agree on climate targets, but they also committed significant funding.\nB: Under no circumstances should this momentum be lost."
  }
]

[
  {
    "level": "Advanced",
    "module_name": "Academic Vocabulary",
    "sub_topic_title": "Formal Language and Hedging",
    "objective": "Enhance academic writing by utilizing advanced vocabulary and learning the technique of 'hedging' to make objective statements.",
    "vocabulary": [
      {
        "term": "To some extent",
        "meaning": "Sampai batas tertentu"
      },
      {
        "term": "Indicate / Suggest",
        "meaning": "Menunjukkan / Mengisyaratkan"
      },
      {
        "term": "Predominantly",
        "meaning": "Sebagian besar / Terutama"
      },
      {
        "term": "Ambiguous",
        "meaning": "Ambigu / Bermakna ganda"
      }
    ],
    "concept": "In academic contexts, claims must be made carefully. 'Hedging' uses modal verbs (could, might), adjectives (probable), or adverbs (perhaps, likely) to soften claims. Avoid absolute words like 'always' or 'prove', and instead use words like 'frequently' or 'indicate'.",
    "example_dialogue": "A: In my essay, I wrote: 'The data proves that this new policy is 100% effective.'\nB: That might be too strong of a claim for an academic paper. You should hedge it: 'The data strongly indicates that this policy is likely effective.'\nA: I see. It makes the argument more objective, defensible, and less arrogant."
  },
  {
    "level": "Advanced",
    "module_name": "Academic Vocabulary",
    "sub_topic_title": "Nominalization (Turning Verbs into Nouns)",
    "objective": "Learn to use nominalization to make sentences more concise, objective, and academically appropriate.",
    "vocabulary": [
      {
        "term": "Nominalization",
        "meaning": "Pembendaan (mengubah kata kerja/sifat menjadi kata benda)"
      },
      {
        "term": "Implementation",
        "meaning": "Implementasi / Pelaksanaan (dari kata 'implement')"
      },
      {
        "term": "Assessment",
        "meaning": "Penilaian (dari kata 'assess')"
      },
      {
        "term": "Fluctuation",
        "meaning": "Fluktuasi / Naik turun (dari kata 'fluctuate')"
      }
    ],
    "concept": "Nominalization is the process of forming nouns from verbs or adjectives. This makes writing more abstract and formal, shifting the focus from the 'doer' of the action to the action itself. Instead of 'We investigated the problem thoroughly', write 'A thorough investigation of the problem was conducted.'",
    "example_dialogue": "A: Can you review my paragraph? I wrote: 'The government decided to expand the highway, which caused the citizens to protest.'\nB: It's grammatically correct, but you can use nominalization to elevate the style. Try: 'The government's decision regarding the highway expansion led to widespread citizen protests.'\nA: Wow, that sounds much more professional and academic."
  }
]

[
  {
    "level": "Advanced",
    "module_name": "Academic Writing",
    "sub_topic_title": "Cohesion, Coherence, and Complex Transitions",
    "objective": "Learn to structure complex academic essays logically and smoothly connect ideas using sophisticated transition devices.",
    "vocabulary": [
      {
        "term": "Nevertheless",
        "meaning": "Meskipun demikian"
      },
      {
        "term": "Furthermore",
        "meaning": "Selanjutnya / Lebih jauh lagi"
      },
      {
        "term": "Conversely",
        "meaning": "Sebaliknya"
      },
      {
        "term": "Notwithstanding",
        "meaning": "Meskipun (Formal)"
      }
    ],
    "concept": "Coherence refers to the logical flow of ideas, while cohesion refers to the linguistic links (transitions) that connect sentences and paragraphs. Use advanced transitions like 'conversely' (for contrast), 'furthermore' (for addition), and 'subsequently' (for sequence) to guide the reader through complex arguments.",
    "example_dialogue": "A: I wrote that the economy is growing rapidly. Then I wrote inflation is rising. How do I connect them smoothly in an essay?\nB: You can use a contrastive transition to show the relationship. For instance: 'The economy is growing rapidly; conversely, inflation rates are rising at an alarming pace.'\nA: That sounds much more cohesive than just putting two separate sentences together."
  },
  {
    "level": "Advanced",
    "module_name": "Academic Writing",
    "sub_topic_title": "Synthesizing Multiple Sources",
    "objective": "Master the skill of combining information from various academic sources to build a strong, unified argument.",
    "vocabulary": [
      {
        "term": "Synthesize",
        "meaning": "Mensintesis / Menggabungkan berbagai elemen"
      },
      {
        "term": "Corroborate",
        "meaning": "Membenarkan / Memperkuat bukti"
      },
      {
        "term": "Contradict",
        "meaning": "Bertentangan dengan"
      },
      {
        "term": "Consensus",
        "meaning": "Kesepakatan bersama"
      }
    ],
    "concept": "Synthesis involves comparing, contrasting, and integrating ideas from multiple authors. Rather than summarizing sources one by one (A says this. B says this), group them by theme. Example: 'While Smith (2020) argues for X, both Jones (2021) and Lee (2022) contradict this view, suggesting that Y is more significant.'",
    "example_dialogue": "A: I have three articles about renewable energy. Should I summarize them in three different paragraphs?\nB: No, that's just a summary. You need to synthesize. Group them by their arguments. If two authors agree on solar power, mention them together to corroborate your point.\nA: Ah, so I use them to support my own thesis, rather than just repeating what they said.\nB: Exactly. That demonstrates advanced critical thinking."
  }
]
